-- ── 1) Guardas de ENTRADA ──────────────────────────────────────────────────────────────────
do $guarda$
declare
  n int; n_pre int; n_pos int; v_lista text;
begin
  if to_regclass('public.work_edition_state') is null then
    raise exception 'mig 205: a 204 (estado de edição) não está aplicada; abortando';
  end if;

  -- Os dados embutidos são os medidos.
  select count(*) into n from mig205_classe;
  if n <> 206 then raise exception 'mig 205: esperava 206 obras nos dados, há %', n; end if;
  if (select count(*) from mig205_classe where state = 'mixed') <> 140
     or (select count(*) from mig205_classe where state = 'r18_only') <> 35
     or (select count(*) from mig205_classe where state = 'single') <> 28
     or (select count(*) from mig205_classe where state = 'unknown') <> 3 then
    raise exception 'mig 205: os dados embutidos não são 140/35/28/3';
  end if;
  if exists (select 1 from mig205_overrides o left join mig205_classe c using (work_id) where c.state is distinct from 'mixed') then
    raise exception 'mig 205: um dos 6 overrides não é de obra mixed';
  end if;

  -- As 206 existem, ativas, pelo ID (o título é só conferência: nunca é a chave).
  select string_agg(c.titulo, '; ') into v_lista
    from mig205_classe c left join public.works w on w.id = c.work_id
   where w.id is null or w.is_archived;
  if v_lista is not null then raise exception 'mig 205: obra(s) ausente(s) ou arquivada(s): %', v_lista; end if;
  select string_agg(c.titulo || ' ≠ ' || w.title, '; ') into v_lista
    from mig205_classe c join public.works w on w.id = c.work_id where w.title <> c.titulo;
  if v_lista is not null then raise exception 'mig 205: título divergente (o id pode estar trocado): %', v_lista; end if;

  -- Estado: ou o LEGADO inteiro (1ª execução) ou o AUDITADO inteiro (re-execução). Mistura = alguém
  -- mexeu no meio, ou o catálogo divergiu da auditoria — não aplico por cima.
  select count(*) filter (where s.decided_by = 'legacy' and s.state = 'mixed'),
         count(*) filter (where s.decided_by = 'audit' and s.state = c.state)
    into n_pre, n_pos
    from mig205_classe c left join public.work_edition_state s on s.work_id = c.work_id;
  if n_pre <> 206 and n_pos <> 206 then
    raise exception 'mig 205: estado misto das 206 (% legadas, % auditadas) — conferir à mão; abortando', n_pre, n_pos;
  end if;

  -- Obra NOVA com r19_edition legado fora da auditoria: o catálogo mudou desde a medição. Ela
  -- precisa ser classificada antes (esta migration não decide sem evidência).
  select string_agg(w.title, '; ') into v_lista
    from public.work_edition_state s join public.works w on w.id = s.work_id
   where s.decided_by = 'legacy' and s.work_id not in (select work_id from mig205_classe);
  if v_lista is not null then
    raise exception 'mig 205: obra(s) com r19_edition LEGADO fora das 206 auditadas: % — classificar antes', v_lista;
  end if;

  if n_pre = 206 then
    select count(*) into n from mig205_overrides o join public.works w on w.id = o.work_id where w.adult_override is true;
    if n <> 6 then raise exception 'mig 205: esperava os 6 overrides = true, há % — a decisão humana mudou; conferir', n; end if;

    select count(*) into n
      from mig205_tags_erradas e
      join public.tags t on t.slug = e.tag_slug
      join public.work_tags wt on wt.work_id = e.work_id and wt.tag_id = t.id;
    if n <> (select count(*) from mig205_tags_erradas) then
      raise exception 'mig 205: esperava % vínculo(s) de tag errada, existem % — o catálogo mudou; remedir', (select count(*) from mig205_tags_erradas), n;
    end if;

    if not exists (select 1 from public.tag_alias a join public.tags t on t.id = a.canonical_tag_id
                    where a.alias_slug = 'r19-with-r15-version' and t.slug = 'r19-version')
       or (select count(*) from public.tag_alias a join public.tags t on t.id = a.canonical_tag_id
            where a.alias_slug in ('uncensored-version-available', 'official-english-uncensored', 'english-company-added-censorship')
              and t.slug = 'r19-disponivel') <> 3
       or exists (select 1 from public.tags where slug = 'uncensored-version-available') then
      raise exception 'mig 205: os aliases não estão no estado medido — conferir à mão';
    end if;
  end if;
end
$guarda$;

-- ── 2) Retrato de ANTES (guardas de saída) ───────────────────────────────────────────────────
drop table if exists pg_temp.mig205_works_pre;
create temp table mig205_works_pre on commit drop as
  select id, is_adult, r19_edition, edition_state, adult_auto, adult_reason, adult_override from public.works;
drop table if exists pg_temp.mig205_wt_pre;
create temp table mig205_wt_pre on commit drop as select work_id, tag_id from public.work_tags;
drop table if exists pg_temp.mig205_tags_pre;
create temp table mig205_tags_pre on commit drop as
  select id, slug, name, adult_indicator, adult_indicator_strong, adult_score_tier, marks_r19_edition from public.tags;
drop table if exists pg_temp.mig205_alias_pre;
create temp table mig205_alias_pre on commit drop as select alias_slug, canonical_tag_id from public.tag_alias;
drop table if exists pg_temp.mig205_notas_pre;
create temp table mig205_notas_pre on commit drop as
  select md5(coalesce(string_agg(concat_ws(':', work_id, criterion_slug, score, source), ',' order by work_id, criterion_slug), '')) h
    from public.category_scores;

-- ── 3) O plano do adult_auto (só wrong_signal, só para baixo) ────────────────────────────────
drop table if exists pg_temp.mig205_plano_auto;
create temp table mig205_plano_auto on commit drop as
with ws as (select work_id from mig205_classe where classe = 'wrong_signal'),
sinais as (
  select w.id, w.adult_auto, w.adult_reason,
         coalesce((select cs.score from public.category_scores cs
                    where cs.work_id = w.id and cs.criterion_slug = 'adult_content'), 0) as nota,
         -- SEM as tags erradas (pelo SLUG da lista — independe de a 205 já ter rodado).
         coalesce(bool_or(t.adult_indicator_strong) filter (where e.work_id is null), false) as strong_resto,
         coalesce(bool_or(t.adult_indicator and not t.adult_indicator_strong) filter (where e.work_id is null), false) as soft_resto
    from public.works w
    join ws on ws.work_id = w.id
    left join public.work_tags wt on wt.work_id = w.id
    left join public.tags t on t.id = wt.tag_id
    left join mig205_tags_erradas e on e.work_id = w.id and e.tag_slug = t.slug
   group by w.id, w.adult_auto, w.adult_reason
),
decisao as (
  select s.*,
         case when s.adult_reason = 'ai_review' then true
              else s.strong_resto or (s.soft_resto and s.nota >= 7) end as auto_depois,
         case when s.adult_reason = 'ai_review' then 'ai_review'
              when s.strong_resto then 'tag_explicit'
              when s.soft_resto and s.nota >= 7 then 'tag_soft_score' end as motivo_depois
    from sinais s
   where s.adult_auto            -- só DESLIGA: obra com adult_auto = false fica como está
)
select id, adult_auto as auto_antes, adult_reason as motivo_antes, auto_depois, motivo_depois
  from decisao
 where (auto_depois, motivo_depois) is distinct from (adult_auto, adult_reason);

do $guarda$
declare n_plano int; n_esperado int; n_bate int; n_sobe int;
begin
  select count(*) into n_sobe from mig205_plano_auto where auto_depois and not auto_antes;
  if n_sobe > 0 then raise exception 'mig 205: % obra(s) passariam a adult_auto = true — esta migration só desliga', n_sobe; end if;
  -- Na re-execução o plano é vazio (já aplicado); na 1ª tem de ser exatamente o medido.
  select count(*) into n_plano from mig205_plano_auto;
  if n_plano > 0 then
    select count(*) into n_esperado from mig205_auto_esperado;
    select count(*) into n_bate from mig205_plano_auto p join mig205_auto_esperado e on e.work_id = p.id
     where e.auto_depois = p.auto_depois and e.motivo_depois is not distinct from p.motivo_depois;
    if n_plano <> n_esperado or n_bate <> n_esperado then
      raise exception 'mig 205: o recálculo de adult_auto daria % mudança(s) (% batem) e a auditoria mediu % — remedir', n_plano, n_bate, n_esperado;
    end if;
  end if;
end
$guarda$;

-- ── 4) Backup para o rollback (a 1ª execução guarda o ORIGINAL; re-execução não sobrescreve) ──
create schema if not exists bkp;
create table if not exists bkp.mig205_estado_antes (
  work_id uuid primary key, state text not null, basis text not null, decided_by text not null,
  evidence jsonb not null, evidence_fetched_at timestamptz, r18_extra_chapters boolean not null,
  decided_at timestamptz not null, salvo_em timestamptz not null default now());
create table if not exists bkp.mig205_works_antes (
  work_id uuid primary key,
  adult_auto boolean not null, adult_reason text, adult_override boolean,
  adult_auto_depois boolean not null, adult_reason_depois text, adult_override_depois boolean,
  salvo_em timestamptz not null default now());
create table if not exists bkp.mig205_work_tags_removidas (
  work_id uuid not null, tag_id uuid not null, tag_slug text not null, source text, confidence real,
  created_at timestamptz, motivo text not null, salvo_em timestamptz not null default now(),
  primary key (work_id, tag_id));
create table if not exists bkp.mig205_tag_alias_antes (
  alias_slug text primary key, canonical_tag_id uuid, salvo_em timestamptz not null default now());
create table if not exists bkp.mig205_tag_criada (
  tag_id uuid primary key, slug text not null, salvo_em timestamptz not null default now());
comment on table bkp.mig205_estado_antes is 'mig 205: os estados LEGADOS (mig 204) das 206 obras, antes da classificação auditada. Usado por scripts/rollback/205_rollback.sql.';
comment on table bkp.mig205_works_antes is 'mig 205: adult_auto/adult_reason das wrong_signal recalculadas, antes e depois (adult_override só como conferência: a 205 não o toca).';
comment on table bkp.mig205_work_tags_removidas is 'mig 205: os vínculos de tag removidos (R19 disponível das 66 não-mixed, r19 das wrong_signal, R19 Version de 6 mixed).';
comment on table bkp.mig205_tag_alias_antes is 'mig 205: os 4 aliases antes da correção (canonical_tag_id NULL = o alias não existia).';
comment on table bkp.mig205_tag_criada is 'mig 205: a tag "Uncensored Version Available" restaurada (neutra).';

insert into bkp.mig205_estado_antes (work_id, state, basis, decided_by, evidence, evidence_fetched_at, r18_extra_chapters, decided_at)
select s.work_id, s.state, s.basis, s.decided_by, s.evidence, s.evidence_fetched_at, s.r18_extra_chapters, s.decided_at
  from public.work_edition_state s join mig205_classe c using (work_id)
 where s.decided_by = 'legacy'
on conflict (work_id) do nothing;

insert into bkp.mig205_work_tags_removidas (work_id, tag_id, tag_slug, source, confidence, created_at, motivo)
select wt.work_id, wt.tag_id, t.slug, wt.source, wt.confidence, wt.created_at, e.motivo
  from mig205_tags_erradas e
  join public.tags t on t.slug = e.tag_slug
  join public.work_tags wt on wt.work_id = e.work_id and wt.tag_id = t.id
on conflict (work_id, tag_id) do nothing;
-- A tag de exibição sai das obras que deixam de ser mixed (pelo gatilho da 204); o vínculo original
-- (com a procedência dele) é guardado aqui.
insert into bkp.mig205_work_tags_removidas (work_id, tag_id, tag_slug, source, confidence, created_at, motivo)
select wt.work_id, wt.tag_id, t.slug, wt.source, wt.confidence, wt.created_at,
       'tag de exibição de mixed; a auditoria classificou a obra como ' || c.state
  from mig205_classe c
  join public.work_tags wt on wt.work_id = c.work_id
  join public.tags t on t.id = wt.tag_id and t.marks_r19_edition
 where c.state <> 'mixed'
on conflict (work_id, tag_id) do nothing;

insert into bkp.mig205_tag_alias_antes (alias_slug, canonical_tag_id)
select v.alias_slug, a.canonical_tag_id
  from (values ('r19-with-r15-version'), ('uncensored-version-available'),
               ('official-english-uncensored'), ('english-company-added-censorship')) v(alias_slug)
  left join public.tag_alias a on a.alias_slug = v.alias_slug
 where not exists (select 1 from public.tags t where t.slug = 'uncensored-version-available')
on conflict (alias_slug) do nothing;

-- ── 5) Aplicar ──────────────────────────────────────────────────────────────────────────────
-- 5a) Os 206 estados: legado → auditado. O gatilho da 204 refaz o espelho e a tag de exibição.
update public.work_edition_state s
   set state = c.state,
       basis = c.basis,
       decided_by = 'audit',
       r18_extra_chapters = c.r18_extra_chapters,
       evidence = c.evidence || jsonb_build_object('estado_legado_mig204', s.evidence)
                  || coalesce((select jsonb_build_object('override_work_level', jsonb_build_object(
                                 'adult_override', true,
                                 'classificacao_auditoria', o.classificacao,
                                 'decisao', 'mantido na fase 1: a página ainda não separa nota/tags por edição; '
                                            'remover na fase 2, quando a versão normal puder ser apresentada'))
                                 from mig205_overrides o where o.work_id = s.work_id), '{}'::jsonb),
       evidence_fetched_at = c.fetched_at,
       decided_at = now()
  from mig205_classe c
 where s.work_id = c.work_id and s.decided_by = 'legacy';

-- 5b) As tags que a auditoria provou erradas.
delete from public.work_tags wt
 using mig205_tags_erradas e, public.tags t
 where t.slug = e.tag_slug and wt.tag_id = t.id and wt.work_id = e.work_id;

-- 5c) adult_auto das wrong_signal, só para baixo.
insert into bkp.mig205_works_antes (work_id, adult_auto, adult_reason, adult_override, adult_auto_depois, adult_reason_depois, adult_override_depois)
select p.id, p.auto_antes, p.motivo_antes, w.adult_override, p.auto_depois, p.motivo_depois, w.adult_override
  from mig205_plano_auto p join public.works w on w.id = p.id
on conflict (work_id) do nothing;
update public.works w
   set adult_auto = p.auto_depois, adult_reason = p.motivo_depois
  from mig205_plano_auto p
 where w.id = p.id;

-- 5d) Aliases.
insert into public.tags (slug, name, tag_group_id, origin, adult_indicator, adult_indicator_strong, marks_r19_edition, reviewed_at)
select 'uncensored-version-available', 'Uncensored Version Available', g.id, 'manual', false, false, false, now()
  from public.tag_group g
 where g.slug = 'format'
   and not exists (select 1 from public.tags where slug = 'uncensored-version-available');
insert into bkp.mig205_tag_criada (tag_id, slug)
select id, slug from public.tags where slug = 'uncensored-version-available'
on conflict (tag_id) do nothing;

delete from public.tag_alias where alias_slug = 'uncensored-version-available';
update public.tag_alias a
   set canonical_tag_id = t.id
  from public.tags t
 where t.slug = 'uncensored-version-available'
   and a.alias_slug in ('official-english-uncensored', 'english-company-added-censorship')
   and a.canonical_tag_id is distinct from t.id;
update public.tag_alias a
   set canonical_tag_id = t.id
  from public.tags t
 where t.slug = 'r19-disponivel'
   and a.alias_slug = 'r19-with-r15-version'
   and a.canonical_tag_id is distinct from t.id;

-- ── 6) Guardas de SAÍDA ─────────────────────────────────────────────────────────────────────
do $guarda$
declare
  n int; n_up int; n_down int; n_mixed_vis int; n_only int; v_lista text;
begin
  -- Estados auditados.
  select count(*) into n from public.work_edition_state s join mig205_classe c using (work_id)
   where s.decided_by = 'audit' and s.state = c.state and s.basis = c.basis;
  if n <> 206 then raise exception 'mig 205: só % das 206 ficaram com o estado auditado', n; end if;
  if exists (select 1 from public.work_edition_state where decided_by = 'legacy') then
    raise exception 'mig 205: sobrou estado legado';
  end if;

  -- A ponte r19_edition = exatamente as 140 mixed; a tag de exibição idem.
  select count(*) into n from public.works where r19_edition;
  if n <> 140 or exists (select 1 from public.works w join mig205_classe c on c.work_id = w.id
                          where w.r19_edition <> (c.state = 'mixed')) then
    raise exception 'mig 205: r19_edition não é exatamente o conjunto mixed (% obras)', n;
  end if;
  select count(*) into n from public.work_tags wt join public.tags t on t.id = wt.tag_id where t.marks_r19_edition;
  if n <> 140 or exists (select 1 from public.work_tags wt join public.tags t on t.id = wt.tag_id and t.marks_r19_edition
                          left join mig205_classe c on c.work_id = wt.work_id
                          where c.state is distinct from 'mixed') then
    raise exception 'mig 205: a tag "R19 disponível" não está exatamente nas 140 mixed (% vínculos)', n;
  end if;

  -- As mixed: no "só 18+" todas; para quem oculta 18+, todas MENOS as 6 com override (mantidos).
  select count(*) filter (where not w.is_adult), count(*) filter (where w.is_adult or w.r19_edition)
    into n_mixed_vis, n_only
    from public.works w join mig205_classe c on c.work_id = w.id where c.state = 'mixed';
  if n_mixed_vis <> 134 or n_only <> 140 then
    raise exception 'mig 205: mixed visíveis para quem oculta 18+ = %, no só 18+ = % (esperado 134/140)', n_mixed_vis, n_only;
  end if;
  if exists (select 1 from public.works w join mig205_overrides o on o.work_id = w.id
              where w.adult_override is not true or not w.is_adult) then
    raise exception 'mig 205: um dos 6 overrides deixou de bloquear a obra';
  end if;
  -- r18_only e unknown: o estado liga o gate (salvo decisão manual).
  if exists (select 1 from public.works w join mig205_classe c on c.work_id = w.id
              where c.state in ('r18_only', 'unknown') and w.is_adult is distinct from coalesce(w.adult_override, true)) then
    raise exception 'mig 205: obra r18_only/unknown fora do gate sem decisão manual';
  end if;

  -- Nenhuma obra FORA das 206 mudou.
  select count(*) into n
    from mig205_works_pre a join public.works w on w.id = a.id
   where a.id not in (select work_id from mig205_classe)
     and (w.is_adult, w.r19_edition, w.edition_state, w.adult_auto, w.adult_reason, w.adult_override)
         is distinct from (a.is_adult, a.r19_edition, a.edition_state, a.adult_auto, a.adult_reason, a.adult_override);
  if n > 0 then raise exception 'mig 205: % obra(s) FORA das 206 mudaram', n; end if;

  -- adult_auto: nenhuma subida; só o plano mudou.
  select count(*) into n from mig205_works_pre a join public.works w on w.id = a.id
   where w.adult_auto and not a.adult_auto;
  if n > 0 then raise exception 'mig 205: % obra(s) ganharam adult_auto = true', n; end if;
  select count(*) into n from mig205_works_pre a join public.works w on w.id = a.id
   where (w.adult_auto, w.adult_reason) is distinct from (a.adult_auto, a.adult_reason)
     and a.id not in (select id from mig205_plano_auto);
  if n > 0 then raise exception 'mig 205: % obra(s) fora do plano mudaram de adult_auto/adult_reason', n; end if;

  -- adult_override: intocado em TODAS as obras (os 6 true continuam; nenhum false novo).
  select count(*) into n from mig205_works_pre a join public.works w on w.id = a.id
   where w.adult_override is distinct from a.adult_override;
  if n > 0 then raise exception 'mig 205: % override(s) mudaram — esta migration não toca adult_override', n; end if;

  -- Nota: intocada.
  if (select h from mig205_notas_pre) is distinct from (
       select md5(coalesce(string_agg(concat_ws(':', work_id, criterion_slug, score, source), ',' order by work_id, criterion_slug), ''))
         from public.category_scores) then
    raise exception 'mig 205: category_scores mudou — esta migration não pode tocar nota';
  end if;

  -- work_tags: só saíram os vínculos planejados (66 da tag de exibição + as erradas); nada entrou.
  select count(*) into n from public.work_tags wt
   where not exists (select 1 from mig205_wt_pre p where p.work_id = wt.work_id and p.tag_id = wt.tag_id);
  if n > 0 then raise exception 'mig 205: % vínculo(s) de tag NOVOS', n; end if;
  select count(*) into n from mig205_wt_pre p
   where not exists (select 1 from public.work_tags wt where wt.work_id = p.work_id and wt.tag_id = p.tag_id)
     and not exists (select 1 from bkp.mig205_work_tags_removidas b where b.work_id = p.work_id and b.tag_id = p.tag_id);
  if n > 0 then raise exception 'mig 205: % vínculo(s) de tag sumiram fora do plano', n; end if;

  -- tags: só a restaurada entrou; nenhuma flag de gate mudou.
  select count(*) into n from mig205_tags_pre a join public.tags t using (id)
   where (t.slug, t.name, t.adult_indicator, t.adult_indicator_strong, t.adult_score_tier, t.marks_r19_edition)
         is distinct from (a.slug, a.name, a.adult_indicator, a.adult_indicator_strong, a.adult_score_tier, a.marks_r19_edition);
  if n > 0 then raise exception 'mig 205: % tag(s) existentes mudaram', n; end if;
  select string_agg(slug, ', ') into v_lista from public.tags t where not exists (select 1 from mig205_tags_pre a where a.id = t.id)
     and t.slug <> 'uncensored-version-available';
  if v_lista is not null then raise exception 'mig 205: tags inesperadas criadas: %', v_lista; end if;
  if exists (select 1 from public.tags where slug = 'uncensored-version-available'
              and (adult_indicator or adult_indicator_strong or marks_r19_edition or adult_score_tier is not null)) then
    raise exception 'mig 205: a tag de censura restaurada liga algum sinal';
  end if;

  -- tag_alias: só os 4 planejados.
  select count(*) into n from (
    select alias_slug, canonical_tag_id from mig205_alias_pre
    except select alias_slug, canonical_tag_id from public.tag_alias) d
   where d.alias_slug not in ('r19-with-r15-version', 'uncensored-version-available',
                              'official-english-uncensored', 'english-company-added-censorship');
  if n > 0 then raise exception 'mig 205: % alias(es) fora do plano mudaram', n; end if;

  -- O efeito no gate é o MEDIDO.
  select count(*) filter (where w.is_adult and not a.is_adult), count(*) filter (where a.is_adult and not w.is_adult)
    into n_up, n_down
    from mig205_works_pre a join public.works w on w.id = a.id;
  if (n_up, n_down) is distinct from (42, 0) and (n_up, n_down) is distinct from (0, 0) then
    raise exception 'mig 205: is_adult % passam a 18+ e % saem (medido: 42 e 0) — remedir', n_up, n_down;
  end if;

  raise notice 'mig 205: 206 estados auditados (140 mixed · 35 r18_only · 28 single · 3 unknown) · % passam a 18+ · % saem · notas intocadas', n_up, n_down;
end
$guarda$;
